assert contenu is not None, "Aucun fichier FTS (.xlsx/.csv) déposé."

xl = pd.ExcelFile(io.BytesIO(contenu))
sh = next((s for s in xl.sheet_names if "DATASET" in s.upper()), xl.sheet_names[0])
